// dist scan: find routes that HAVE a translated page yaml but still render EN h1/title.
// Usage (after npm run build): node tools/i18n-endiff.mjs
// Writes tools/_work/endiff.json + per-lang console report.
// Auto-excludes the empty noindex compare auto-slug pages (225 pages generated by
// [lang]/compare/[slug].astro that compareTemplate cannot build) — pre-existing EN-side
// site bug, out of l10n scope. Only the 8 explicit compare routes + the hub are checked.
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { createRequire } from 'node:module';

const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const require = createRequire(path.join(ROOT, 'package.json'));
const YAML = require('yaml');

const DIST = path.join(ROOT, 'dist');
const PAGES = path.join(ROOT, 'src/data/pages');
const OUT = path.join(ROOT, 'tools', '_work', 'endiff.json');
const langs = ['fr', 'de', 'es', 'pt', 'ar', 'it', 'ru', 'pl', 'nl', 'sv', 'no', 'el', 'fi', 'da'];
const EXPLICIT_COMPARE = new Set([
  'aluminum-vs-fiberglass',
  'inflatable-pool-factory-vs-traditional-manufacturers',
  'commercial-vs-recreational-rib',
  'inflatable-vs-hardboard',
  'pvc-vs-hypalon',
  'rib-vs-dinghy',
  'sup-vs-kayak',
  'sup-vs-rib',
]);

const decode = (s) =>
  String(s)
    .replace(/<[^>]+>/g, ' ')
    .replace(/&#39;/g, "'")
    .replace(/&apos;/g, "'")
    .replace(/&amp;/g, '&')
    .replace(/&quot;/g, '"')
    .replace(/&#x27;/g, "'")
    .replace(/&nbsp;/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();

const extract = (html) => {
  const h1 = html.match(/<h1[^>]*>([\s\S]*?)<\/h1>/);
  const title = html.match(/<title[^>]*>([\s\S]*?)<\/title>/);
  return { h1: h1 ? decode(h1[1]) : '', title: title ? decode(title[1]) : '' };
};

const loadYaml = (p) => {
  try {
    return YAML.parse(fs.readFileSync(p, 'utf8'));
  } catch {
    return null;
  }
};

const enDir = path.join(DIST, 'en');
const routes = fs
  .readdirSync(enDir, { recursive: true })
  .map((f) => String(f))
  .filter((f) => f.endsWith('index.html'))
  .map((f) => (f === 'index.html' ? '' : f.replace(/\\index\.html$|\/index\.html$/, '').replace(/\\/g, '/')))
  .filter((r) => r !== 'keystatic' && !r.startsWith('keystatic/'))
  .filter((r) => {
    const seg = r.split('/');
    if (seg[0] !== 'compare') return true;
    const slug = seg[1];
    return !slug || EXPLICIT_COMPARE.has(slug);
  })
  .sort();

const enHtml = new Map();
for (const r of routes) {
  const p = r === '' ? path.join(enDir, 'index.html') : path.join(enDir, r, 'index.html');
  enHtml.set(r, fs.readFileSync(p, 'utf8'));
}

const yamlCache = new Map();
const getYaml = (lang, route) => {
  const slug = route.replace(/\//g, '-');
  const key = `${lang}/${slug}`;
  if (yamlCache.has(key)) return yamlCache.get(key);
  let v = undefined; // undefined=no file, null=parse fail, obj=parsed
  const p = lang === 'en' ? path.join(PAGES, slug + '.yaml') : path.join(PAGES, lang, slug + '.yaml');
  if (fs.existsSync(p)) v = loadYaml(p) ?? null;
  yamlCache.set(key, v);
  return v;
};

const out = {};
for (const lang of langs) {
  const rows = [];
  for (const r of routes) {
    const lp = path.join(DIST, lang, r, 'index.html');
    if (!fs.existsSync(lp)) continue;
    const e = extract(enHtml.get(r));
    const l = extract(fs.readFileSync(lp, 'utf8'));
    const ly = getYaml(lang, r);
    const ey = getYaml('en', r);
    const sameH1 = l.h1 && l.h1 === e.h1;
    const sameTitle = l.title && l.title === e.title;
    if (!sameH1 && !sameTitle) continue;
    if (!ly || !ey) continue; // no translated yaml -> by-design fallback, skip here
    const strip = (v) => (v ? decode(String(v)) : '');
    const lt = strip(ly.hero?.title);
    const et = strip(ey.hero?.title);
    let cls;
    if (sameH1) {
      cls = lt && et && lt !== et ? 'RENDER-BUG' : 'YAML-EN-CONTENT';
    } else {
      cls = 'TITLE-ONLY';
    }
    rows.push({ route: r, cls, sameH1, sameTitle, lt: lt.slice(0, 60), et: et.slice(0, 60) });
  }
  out[lang] = rows;
  if (rows.length) {
    console.log(`\n=== ${lang}: ${rows.length} routes with translated yaml but EN-similar output ===`);
    for (const row of rows) {
      console.log(
        `  [${row.cls}] ${row.route} h1same=${row.sameH1} titlesame=${row.sameTitle}${row.cls === 'YAML-EN-CONTENT' ? '' : ' lt=' + row.lt + ' et=' + row.et}`
      );
    }
  } else {
    console.log(`\n=== ${lang}: all yaml-backed routes fully localized ===`);
  }
}

fs.mkdirSync(path.dirname(OUT), { recursive: true });
fs.writeFileSync(OUT, JSON.stringify(out, null, 1));
